window.FARM_PLANS = {"steakhouse-financial":{"s":[["On Base: open Morpho, filter curator Steakhouse Financial, sort by TVL; the Base High Yield USDC vault is the flagship.","free","15 min"],["Bridge USDC to Base through the official Base bridge or any major bridge and hold a little ETH on Base for gas.","~$1-5 gas and bridge fees","10 min"],["Approve and deposit USDC into the chosen vault in two txs for ERC-4626 shares; yield accrues through the share price.","under $0.10 gas/tx on Base","minutes"],["Robinhood angle: Steakhouse curates the USDG vault behind Robinhood Earn at $537M and 3.7% APY, but deposits are switched off.","free","5 min"],["Hold indefinitely, no lock-up; withdrawals instant subject to liquidity. Exit if the risk rating drops or a market looks stressed.","deposit held","weeks"]]},"sentora-curator":{"s":[["Get PYUSD or USDC in an EVM wallet like MetaMask or Rabby.","$1-5 gas per tx","10 min"],["Open Morpho, find a Sentora-curated vault (PYUSD Main), and check the curator address, APY and performance fee.","free","10 min"],["Approve the vault, then deposit; vault shares accrue the lending yield after the curator fee.","$1-5 gas per tx","5 min"],["Hold for weeks and check live APY and fees on Morpho; some Sentora products are not open to US residents.","deposit held","weeks"],["Withdraw from the vault in the Morpho app; never pay anyone to claim a Sentora reward.","$1-5 gas per tx","10 min"]]},"gauntlet":{"s":[["Get USDC on Base, where gas is under $0.10, not Ethereum mainnet at $2-10 a tx.","under $0.10 gas on Base","10 min"],["Open Morpho or Gauntlet vaultbook and pick a vault; USDC Prime is the flagship.","free","15 min"],["Deposit USDC with approve + deposit for ERC-4626 shares; no lock-up.","under $0.25 on Base","5 min"],["Hold for weeks; lending interest accrues to the share price, nothing to claim.","deposit held","weeks"],["Check the vault still accepts deposits: Gauntlet paused V1 allocations ~5 Nov 2026, prefer V2 and Prime.","free","5 min"]]},"polymarket-international":{"s":[["Get pUSD or USDC on Polygon in a wallet, and check your country is not on the blocked list.","cents of gas on Polygon","10 min"],["Pick liquid markets (crypto, sports, politics) and post resting limit orders as a maker; makers pay 0% fee.","taker fees only if you take; makers 0%","15 min"],["Earn daily USDC Liquidity Rewards on resting orders plus 15-25% of fees back as maker rebates.","nothing but the orders","10 min/day"],["Hold positions in selected long-dated markets for Holding Rewards, about 4% annualised where offered.","capital held in positions","weeks"],["Keep a log of markets, volume and rewards; never wash-trade, and never connect to a site claiming a POLY claim page.","free","5 min/week"]]},"veda":{"s":[["Kraken DeFi Earn: allocate USDC, or BTC and xStocks where eligible, to a Veda-powered vault; no self-custody needed.","no gas paid directly","10 min"],["Self-custody: EtherFi Liquid vaults. Deposit weETH or ETH into one, like the Super Symbiotic vault, on ether.fi.","$3-10 gas per tx","10 min"],["Or use MetaMask Money Account or Plasma vaults, also Veda-powered, if you hold assets there; the same points accrual applies.","gas depends on the chain","10 min"],["Hold: points equal USD balance x 0.01 x days held, with per-vault multipliers; duration matters more than hopping vaults.","deposit held","months"],["Check your points on the Veda dashboard and track multipliers; withdrawals are non-custodial, but each vault has its own timing.","free","5 min/week"]]},"usdd":{"s":[["Buy USDD and stake for sUSDD. Get USDD on Tron by swapping USDT to USDD on SunSwap or 1:1 via the Peg Stability Module.","near-zero if you hold or rent TRX energy","10 min"],["Or mint it yourself: open a USDD vault, deposit TRX, sTRX, USDT or WBTC, and mint USDD, keeping the ratio well above the minimum.","a few TRX per tx","10 min, then monitor ratio"],["Lend on JustLend, Tron largest money market: supply USDD to earn supply APY, sometimes topped up with TRON DAO Reserve incentives.","a few TRX per tx","10 min"],["Optional LP on SunSwap: provide USDD-USDT or USDD-TRX liquidity for trading fees plus mining rewards, only if you accept IL risk.","a few TRX per tx, plus IL risk","10 min"],["Monitor the peg: USDD fell to ~$0.93 in Jun 2022; the 2.0 model is over-collateralized near 148%, but the reserve is TRX-heavy.","free","5 min/week"]]},"bitfi-basis":{"s":[["Get USDT, USDC or BTC on BNB Chain, Ethereum or Base in a wallet.","$1-5 gas per tx","10 min"],["Open app.bitfi.one and mint bfUSD from USDT/USDC, or bfBTC from BTC.","gas to mint","10 min"],["Hold bfUSD, or stake it into the Horizon or Pulsar vaults, to earn HODL points each epoch (about daily).","gas to stake","10 min"],["Complete the bfUSD one-time quests and check your points balance on the points page.","free","10 min"],["Optional: LP bfUSD on Curve for extra points, and watch impermanent loss on the pair.","gas plus LP risk","15 min"],["Track points per epoch; withdraw through the BitFi app only, and verify the contract address first.","gas to withdraw","10 min"]]},"nonce-capital":{"s":[["Open ether.fi, go to Earn or Liquid, and pick a Nonce-curated Liquid vault: Liquid USD, Liquid ETH or Liquid BTC.","free","15 min"],["Confirm Nonce Capital is listed as curator on the vault page, then deposit USDC, USDT, weETH, WETH or eETH on ETH.","$2-10 gas per tx","15 min"],["Receive liquid vault shares, like liquidUSD or liquidETH; yield auto-compounds as the curator rebalances.","deposit held","minutes"],["Hold 1-3 months: curator vaults are slow, diversified yield, not a points sprint; check allocation monthly.","deposit held","1-3 months"],["Withdraw through the vault redemption or queue and plan exits days ahead: some vaults have a withdrawal queue or cooldown.","$2-10 of gas","days"]]},"onre":{"s":[["Get ONyc at OnRe by connecting Phantom and buying with USDC or sUSDe on Solana; txs cost under $0.10.","under $0.10 per tx","10 min"],["Check the live price against NAV first: primary mint is for qualified investors, so retail usually buys on secondary markets.","free","5 min"],["Base leg at 1x: simply hold ONyc for 1 point per ONyc per day, and hold 60+ days to qualify for the Compounding Rewards Season 1.","ONyc held","60+ days"],["Higher multipliers: supply ONyc as collateral on Kamino or Loopscale for 3x, or LP ONyc with USDC on Orca or Raydium for 2x.","under $0.10 a tx, plus liquidation and IL risk","15 min"],["Track points on the leaderboard at OnRe and hold through at least one underwriting cycle of 60+ days.","free","60+ days"]]},"rockawayx":{"s":[["Ethereum leg: on Morpho, filter by curator RockawayX and pick a vault by risk; USDC Prime is conservative at 0% fee quoted.","free","15 min"],["Deposit USDC, or wETH for the wETH vault, on ETH; gas is $2-10 per tx and you receive the vault share token.","$2-10 gas per tx","15 min"],["Solana leg: on Kamino find the RockawayX RWA USDC vault, ~$41.9M supply and 4.8% yield, mainly OnRe and PRIME markets.","under $0.10 per tx","10 min"],["Hold 1-3 months; the curator rebalances across isolated Morpho and Kamino markets, with 3-7 day timelocks on Morpho changes.","deposit held","1-3 months"],["Redeem vault shares back to USDC or wETH through Morpho or Kamino when exiting; allow for withdrawal queues on illiquid markets.","$2-10 on ETH, under $0.10 on Solana","days"]]},"bittensor-dtao":{"s":[["Buy TAO on a major CEX; this is a live, volatile asset near $180, not a free farm.","exchange fees vary","10 min"],["Set up a Bittensor wallet and transfer TAO to the Bittensor chain (Subtensor).","small transfer fee","10 min"],["Research subnets on taostats.io for emissions share and validator quality first.","free","20 min"],["Stake TAO to a validator in a subnet; TAO swaps into that subnet alpha and earns emissions every 360 blocks.","small on-chain fee","10 min"],["Unstake anytime to swap alpha back to TAO; alpha can fall sharply and emissions do not guarantee profit.","small on-chain fee","10 min"]]},"upshift":{"s":[["Open Upshift, pick a vault by asset and chain; retail options are Ethereum USDC vaults like Sentora USD or SharpByte RWA.","free","15 min"],["Deposit USDC on ETH with approve + deposit for receipt tokens like upSBRWA or sentUSD; gas is $3-10.","$3-10 gas per tx","5 min"],["Verify the 5x early-deposit boost is still live; it ends when Upshift TVL hits $750M (about $515M in Oct 2026).","free","5 min"],["Partner stacking: supply your receipt token as collateral on Morpho for a 5x multiplier, or LP it on Pendle for up to 7.5x.","$3-10 of gas, plus liquidation risk","15 min"],["Hold for the season: points accrue on size and time, then decay. Withdrawals follow the vault terms, some with 25-hour to 3-day windows.","deposit held","weeks"]]},"opentrade":{"s":[["On WOO X, Staking or Earn, then RWA, pick the High Yield Corporate Bond vault tracking the BlackRock SHYG ETF.","KYC via WOO X, no lockup","minutes to subscribe"],["Alternative: open the IXS app, go to Earn, and pick the SHYG Vault; deposit USDC on Avalanche, where gas is under $0.50.","under $0.50 gas on Avalanche","10 min"],["Alternative: use Plume Nest vaults powered by OpenTrade; deposit stablecoins into Nest for nTOKENS backed by WisdomTree funds.","cents of gas on Plume","10 min"],["Direct route, institutional only: onboard at opentrade.io with KYB, then deposit USDC, USDT or EURC into a vault like Prime+.","KYB over days, then gas","days to onboard"],["Hold weeks: yield is fixed income, so expect single-digit APR, not points multiples; the farm thesis is an unconfirmed token.","deposit held","weeks"]]},"hive-protocol":{"s":[["Acquire BTC on an exchange and set up a BSquared-compatible wallet, like MetaMask with B2 added.","exchange fees vary","15 min"],["Open the Hive app and verify it loads from your location; it returned access-restricted to one checker.","free","5 min"],["Bridge and stake BTC into Hive on screen; staking locks BTC to secure the rollup.","a few dollars fees","30 min"],["Hold the stake to accrue $B2 rewards over time; B2 can be sold on exchanges where it lists.","BTC staked","weeks"],["Confirm the unbonding window in the app first, then unstake and withdraw there.","a few dollars gas","per window"]]},"hyperithm":{"s":[["Get USDC on Monad, where gas costs cents: bridge from Ethereum or Arbitrum, or withdraw from an exchange.","bridge fees vary, gas cents","10-30 min"],["Deposit USDC into the Hyperithm Delta Neutral Vault on YieldApp on Monad, ~$73.6M TVL and 10.4% APY.","cents of Monad gas","10 min"],["Hold aHYPER shares; yield comes from delta-neutral strategies, and the vault hit its $65M cap once, so check capacity.","deposit held","weeks"],["Experienced users only: use aHYPER as collateral in Morpho markets on Monad to borrow USDC and loop.","cents of gas, plus liquidation risk","15 min"],["Before sizing up, verify leverage and transparency: Hyperithm used recursive exposure before and later withdrew it.","free","10 min"]]},"plume-vaults":{"s":[["On nest.credit, connect your wallet and pick a vault by asset: nTBILL for T-bills, nWISDOM for WisdomTree funds, nALPHA for credit.","free","15 min"],["Deposit pUSD on Plume or USDC on Solana or Ethereum; gas is cents on Plume and Solana and $2-10 on ETH.","cents on Plume/Solana, $2-10 ETH","10 min"],["Hold the nTOKEN: base RWA yield accrues as the token value rises, and redemption is at market value at any point, no lockup stated.","deposit held","1-3 months"],["Optional multiplier: deploy nTOKENS into partner DeFi, like LP on Rooster DEX on Plume, which earned up to 8x PNP in Season 1.","cents of gas, plus LP risk","15 min"],["Do not present PNP as currently live without checking nest.credit: Season 1 ran Nov 2025 to Mar 2026 and paid out in PLUME.","free","5 min"]]},"k3-capital":{"s":[["Open the Earn page at k3-capital.net and pick a vault: RSETH, NUSD, BOLD, EUROP, USDT or USDT0.","free","15 min"],["Cheapest entry is Monad, where gas costs cents; or use Ethereum vaults for the deepest Euler and IPOR markets.","cents on Monad, $2-10 ETH","10-30 min"],["Deposit the listed asset with approve + deposit; e.g. BOLD into the sBOLD vault on Liquity v2.","cents on Monad, $2-10 ETH","10 min"],["Hold for weeks; K3 rebalances across the underlying protocols and yield accrues to the share price.","deposit held","weeks"],["Withdraw anytime through the same Earn page, subject to liquidity, and check the vault fee and underlying protocol first.","cents on Monad, $2-10 ETH","10 min"]]},"symbiotic":{"s":[["Get stETH or wstETH on ETH by swapping ETH on a DEX or minting through Lido; gas is $2-10 a tx, so size positions at $500 or more.","$2-10 gas per tx","5-10 min"],["Deposit at the Symbiotic restake app and pick a vault with open capacity and a reputable curator; caps have filled before.","$2-10 gas per tx","5 min"],["Deposit weETH into the ether.fi Super Symbiotic vault, historically 1x Symbiotic plus 3x ether.fi plus 3x Veda points.","$2-10 gas per tx","10 min"],["Delegate to a network or operator if the vault requires it: rewards only flow when collateral is actively securing a network.","free","5 min"],["Hold months: points scale with amount, duration and networks secured; prefer veto-slashed or no-slash vaults over the highest APY.","collateral held","months"]]},"defi-saver-asset-management":{"s":[["Get ETH or USDC on Ethereum in a wallet; Ethereum gas is the main cost here.","$2-10 gas per tx","10 min"],["Open DeFi Saver, connect, and pick a protocol (Aave or Morpho) and a position: leveraged long ETH or stable yield.","free to browse","15 min"],["Supply collateral, borrow and loop once with the one-click recipe; read the liquidation price before confirming.","gas per action","15 min"],["Turn on automation (stop-loss or auto-boost) so the position defends itself while you are away.","gas to set up","10 min"],["Hold and monitor the health factor; repay or unwind before it nears liquidation.","deposit held","weeks"],["Close the position through DeFi Saver and log the entry, exits and fees.","gas to close","10 min"]]},"clearstar":{"s":[["Pick a route: earnXRP on Flare for XRP exposure, or a Clearstar Morpho vault on Base or Ethereum for USDC.","free","15 min"],["For earnXRP: get XRP, bridge it to Flare via FAssets to mint FXRP 1:1; Flare gas costs cents.","cents per tx","10 min"],["Open earnXRP in the Xaman wallet Flare Yield app and deposit FXRP; it auto-compounds, no claiming.","cents per tx","10 min"],["For Morpho: get USDC on Base or Ethereum, find the Clearstar vault in the Morpho app, and deposit.","cents on Base, $1-5 on ETH","10 min"],["Hold and monitor: earnXRP targets ~4-10% depending on vault size; Morpho APYs vary by market.","deposit held","weeks"]]},"r25":{"s":[["Sui leg: get rcUSD, the Sui-native stablecoin backed by regulated RWAs, then stake it for rcUSDp, the yield-bearing receipt token.","under $0.05 per transaction on Sui","minutes"],["Or use the Ember or TopNod R25 rcUSD Vault on Sui, a fixed-yield vault at ~12% base APY quoted at launch, with T+4 settlement.","under $0.05 per transaction on Sui","minutes in, T+4 out"],["Pharos leg: deposit USDC into the pRNH Vault on Pharos, exposure to the NYLIM Anemoy high-yield bond portfolio, near 7% annualised.","Pharos gas is cents","10 min"],["Or use the Axil Prime Credit Vault on Pharos via Binance, OKX or Bitget wallets: USDC in, ~14.3% target annualised, 3-month lock.","Pharos gas is cents, locked 3 months","10 min"],["Hold for the vault term and redeem, allowing settlement time: Axil took up to ~7 days, Ember settles T+4.","cents of gas","7 days"]]},"tori-finance":{"s":[["Get USDC or USDT on ETH; Tori is Ethereum-only as its hub, so budget $5-15 total gas for the full flow.","$5-15 of gas for the full flow","10 min"],["Swap for trUSD in Tori; the docs recommend swapping over minting, since a 0.1% fee applies to mint operations.","swap fee plus $2-10 gas","minutes"],["Stake trUSD to strUSD instantly there; yield accrues automatically through the strUSD to trUSD exchange rate.","$2-10 of gas","5 min"],["Mind the 7-day unstaking cooldown: unstaking strUSD always takes 7 days, so treat this as a minimum ~2-week commitment.","locked 7 days on exit","2 weeks"],["Second leg: deposit strUSD or trUSD into the Tori Ecosystem Vault on Upshift or a Pendle PT or YT market maturing 26 Nov 2026.","$2-10 of gas, plus LP risk","15 min"]]},"b14g":{"s":[["Read the security update first: confirm contracts are unpaused and the post-mortem is out, or stop here.","free","5 min"],["BTC holders: open the Merge Marketplace and create an order setting your reward split with the CORE partner.","free","10 min"],["Stake BTC via Core non-custodial BTC staking; BTC stays time-locked on Bitcoin, no bridging or wrapping.","Bitcoin fee only","minutes"],["CORE holders: browse Merge orders, pick one, and stake CORE to activate dual-staking for both sides.","pennies of Core gas","10 min"],["Monitor the position and repayment claims; unstaking follows Core timelock rules, not instant.","free","weeks"]]},"galaxy-curation":{"s":[["Do NOT expect a points or airdrop farm here: the only honest retail play is yield on the Kamino vaults, or nothing.","free","5 min"],["Get USDC or USDT on Solana in a wallet like Phantom or Solflare; Solana gas is fractions of a cent.","fractions of a cent","10 min"],["Open Kamino or Yield.xyz, find the Galaxy USDC or USDT vault, and verify it is official.","free","10 min"],["Deposit USDC or USDT in one tx; yield comes from Kamino borrower activity, no guaranteed APY published.","fractions of a cent","5 min"],["Hold and monitor risk disclosures: vaults carry market, smart-contract and liquidity risk and are NOT principal-protected.","deposit held","weeks"]]},"lofty":{"s":[["Create an account at lofty.ai and complete identity verification; KYC is required, you must be 18+, most countries accepted.","free","1 day"],["Set up Pera Wallet and fund it with a little ALGO for fees plus USDC on Algorand for purchases.","fees are 0.001 ALGO, under $0.001","10 min"],["Browse the marketplace and pick a property; listings show location, rent projections, expenses and reports, tokens ~$50 each.","free","30 min"],["Buy tokens with a 2.5% purchase fee; e.g. $500 buys ~10 tokens minus the fee, and nobody may hold over 15% of one property.","2.5% purchase fee","minutes"],["Hold for months+; net rent accrues daily at midnight UTC, withdrawable in USDC, and you can vote on property decisions.","tokens held","months+"]]}};
